const ee = require('@google/earthengine');
const privateKey = require('./.earthsense-436113-b294c5f5c2dc.json');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const alBayda = ee.Geometry.Point(21.7258, 32.7844); // Coordinates for Al Bayda, Libya

  const date1 = '2023-09-08';
  const date2 = '2023-09-13';

  // 2. Data Acquisition & Check
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/V2/VCMSLCFG');

  // Function to get image and stats for a given date
  const getDailyLightIntensity = async (date, name) => {
    let collection = viirsCollection
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filterBounds(alBayda);

    const collectionSize = await collection.size().getInfo();
    console.log(`${name} Images: ${collectionSize}`);

    if (collectionSize === 0) {
      return { value: null, pixels: 0, status: 'C1' }; // Empty Collection
    }

    // Get the first image (daily composite)
    let image = collection.first();

    // The 'avg_rad' band contains the average radiance.
    // The 'vcmsl' band is a cloud mask and quality flag: 0 means good quality (cloud-free, no stray light).
    // Mask out pixels that are not good quality.
    let maskedImage = image.select('avg_rad').updateMask(image.select('vcmsl').eq(0));

    // Calculate mean radiance and pixel count
    const stats = await maskedImage.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: alBayda,
      scale: 750, // VIIRS DNB nominal resolution is 750m
      maxPixels: 1e9
    }).getInfo();

    const avgRad = stats ? stats['avg_rad'] : null;
    const pixelCount = stats ? stats['avg_rad_count'] : 0; // The count for 'avg_rad'

    console.log(`${name} Pixels: ${pixelCount}`);

    if (pixelCount === 0) {
      return { value: null, pixels: 0, status: 'C2' }; // No Valid Pixels after masking
    }
    if (avgRad === null || isNaN(avgRad)) {
      return { value: null, pixels: pixelCount, status: 'C3' }; // Calculation Failure
    }

    return { value: avgRad, pixels: pixelCount, status: 'OK' };
  };

  const result1 = await getDailyLightIntensity(date1, `Date ${date1}`);
  const result2 = await getDailyLightIntensity(date2, `Date ${date2}`);

  if (result1.status !== 'OK') {
    console.log(result1.status);
    return;
  }
  if (result2.status !== 'OK') {
    console.log(result2.status);
    return;
  }

  // 4. Calculation and 5. Validation & Final Answer
  const intensity1 = result1.value;
  const intensity2 = result2.value;

  console.log(`Intensity ${date1}: ${intensity1.toFixed(3)} nW/cm²/sr`);
  console.log(`Intensity ${date2}: ${intensity2.toFixed(3)} nW/cm²/sr`);

  if (intensity2 < intensity1) {
    console.log("A"); // Yes, intensity decreased
  } else {
    console.log("B"); // No, intensity did not decrease (stayed same or increased)
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
